@Test
public void practice_numCollidedEntries_emptySet() {
    assertEquals(0, mHashSet.numCollidedEntries());
    sPoints += 1;
}

@Test
public void practice_numCollidedEntries_sixItemsTwoCollisions() {
    mHashSet.add("hello");
    mHashSet.add("hi");
    mHashSet.add("caio");
    mHashSet.add("hola");
    mHashSet.add("shalom");
    mHashSet.add("bonjour");
    assertEquals(2, mHashSet.numCollidedEntries());
    sPoints += 1;
}

@Test
public void practice_rehashCount_zeroBeforeFirstRehash() {
    assertEquals(0, mHashSet.rehashCount());
    String[] preThreshold = { "hello", "hi", "caio", "hola", "shalom", "bonjour", "ni-hao", "aloha", "tere", "sveiki" };
    for (String s : preThreshold) mHashSet.add(s);
    assertEquals("rehashCount must still be 0 right at the threshold", 0, mHashSet.rehashCount());
    mHashSet.add("mulishani");
    assertEquals("rehashCount must be exactly 1 after the add that triggered growth", 1, mHashSet.rehashCount());
    sPoints += 1;
}
